fn binary_search(a: &Vec<i32>, key: i32) -> usize {
    let mut lo: usize = 0;
    let mut hi: usize = a.len();

    // Invariant:
    //  0 <= lo <= hi <= a.len()
    // All indices < lo have a[idx] < key.
    // All indices >= hi have a[idx] >= key.
    while lo < hi {
        let mid = lo + (hi - lo) / 2;
        if a[mid] < key {
            // key must go strictly to the right of mid
            lo = mid + 1;
        } else {
            // a[mid] >= key, so key could go at mid or to the left
            hi = mid;
        }
    }

    // At termination, lo == hi is the smallest index
    // such that all elements before it are < key
    // and all elements at or after it are >= key.
    lo
}

